local _0xxr_L1_I1_i1_1l1I1Li1ILL = (bit32 and bit32.bxor) or function(a, b)
    local r, m = 0, 1
    while a > 0 or b > 0 do
        local ra, rb = a % 2, b % 2
        if ra ~= rb then r = r + m end
        a, b, m = math.floor(a / 2), math.floor(b / 2), m * 2
    end
    return r
end

